qss:
QWidget {
    background: #10131a;
    color: #e9edf7;
    font-family: "Segoe UI", "Inter", sans-serif;
    font-size: 10pt;
}
QMainWindow {
    background: #10131a;
}
QLabel {
    background: transparent;
}
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface {
    background: #171b24;
    border: 1px solid #252b36;
    border-radius: 16px;
}
QLabel#TitleLabel {
    font-size: 16pt;
    font-weight: 700;
    color: #ffffff;
}
QLabel#SubtleLabel {
    color: #9ea8ba;
}
QPushButton {
    background: #2a3342;
    color: #f3f6fc;
    border: 1px solid #344054;
    border-radius: 12px;
    padding: 8px 12px;
}
QPushButton:hover {
    background: #334155;
}
QPushButton:pressed {
    background: #253042;
}
QPushButton#AccentButton {
    background: #5b8cff;
    border: 1px solid #6a98ff;
    color: #ffffff;
    font-weight: 700;
}
QPushButton#AccentButton:hover {
    background: #6a98ff;
}
QPushButton#DangerButton {
    background: #4a2228;
    border: 1px solid #6a2e37;
}
QPushButton#DangerButton:hover {
    background: #5e2a31;
}
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser {
    background: #0f141c;
    color: #edf2ff;
    border: 1px solid #2d3748;
    border-radius: 12px;
    padding: 8px;
}
QListWidget::item {
    border-radius: 10px;
    padding: 8px;
    margin: 2px;
}
QListWidget::item:selected {
    background: #243247;
    border: 1px solid #436194;
}
QScrollArea {
    border: none;
    background: transparent;
}
QScrollBar:vertical {
    background: #151922;
    width: 16px;
    margin: 2px;
    border-radius: 6px;
}
QScrollBar::handle:vertical {
    background: #2f3949;
    min-height: 36px;
    border-radius: 7px;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QScrollBar:horizontal { background: #151922; height: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:horizontal { background: #2f3949; min-width: 36px; border-radius: 7px; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0px; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: transparent; }
QCheckBox {
    spacing: 8px;
}
QDialog {
    background: #10131a;
}
QProgressBar {
    border: 1px solid #344054;
    border-radius: 10px;
    background: #111827;
    text-align: center;
    min-height: 18px;
}
QProgressBar::chunk {
    background: #5b8cff;
    border-radius: 8px;
}

QFrame#AssistantBubbleCard { background: #1c2430; border: 1px solid #41638f; border-left: 4px solid #6ea8ff; border-radius: 16px; }
QFrame#UserBubbleCard { background: #243752; border: 1px solid #41638f; border-radius: 16px; }
